#include <optional>
#include <stdexcept>
#include <vector>

std::vector<std::size_t> sliceIndices(std::size_t length, std::optional<long> start, std::optional<long> stop, long step)
{
    if (step == 0) throw std::invalid_argument("slice step cannot be zero");
    const long len{ static_cast<long>(length) };
    const auto adjust{ [&](std::optional<long> value, long missing) {
        if (!value) return missing;
        long v{ *value };
        if (v < 0)
        {
            v += len;
            if (v < 0) v = step < 0 ? -1 : 0;
        }
        else if (v >= len)
        {
            v = step < 0 ? len - 1 : len;
        }
        return v;
    } };
    const long first{ adjust(start, step < 0 ? len - 1 : 0) };
    const long last{ adjust(stop, step < 0 ? -1 : len) };
    std::vector<std::size_t> out;
    if (step > 0)
        for (long i{ first }; i < last; i += step) out.push_back(static_cast<std::size_t>(i));
    else
        for (long i{ first }; i > last; i += step) out.push_back(static_cast<std::size_t>(i));
    return out;
}

long floorDiv(long a, long b)
{
    if (b == 0) throw std::invalid_argument("division by zero");
    long q{ a / b };
    if (a % b != 0 && ((a < 0) != (b < 0))) --q;
    return q;
}

long floorMod(long a, long b)
{
    if (b == 0) throw std::invalid_argument("division by zero");
    long r{ a % b };
    if (r != 0 && ((r < 0) != (b < 0))) r += b;
    return r;
}

